create function pg_temp.ot_dynamic(family text,slide_type text)returns public.dynamic_slides language sql stable as $fn$
 select jsonb_populate_record(null::public.dynamic_slides,jsonb_build_object('id','60000000-0000-4000-8000-000000000285','tenant_id','10000000-0000-4000-8000-000000000285','name','Controlled OnzeTrots source','slide_type',slide_type,'orientation','landscape','data_source_id',source.data_source_id,'configuration_json',jsonb_build_object('schemaVersion',1,'maxItems',200,'context',pg_temp.ot_context(),'teamSelection',jsonb_build_object('mode','selected','teamContexts',jsonb_build_array(pg_temp.ot_context())),'teamContexts',jsonb_build_array(pg_temp.ot_context()),'blueprintKey',case when slide_type='sport_visitor_arrivals'then'sportlink.visitor_arrivals'when slide_type='sport_standing'then'sportlink.pool_standings'else null end,'syncConfiguration',jsonb_set(jsonb_set(pg_temp.ot_configuration(),'{slideType}',to_jsonb(slide_type)),'{seed,family}',to_jsonb(family)))))from ot_source source;
$fn$;
create temporary table ot_snapshots(name text,value jsonb);
