select is((select value#>>'{syncScope,ownClubId}'from ot_snapshots where name='welcome'),'own-club','canonical scope resolves the club within the selected source');
select is((select value#>'{syncScope,ownTeamIds}'from ot_snapshots where name='welcome'),'["own-team"]'::jsonb,'canonical scope retains the exact authorized team ID');
select is((select jsonb_array_length(value#>'{sport,items}')from ot_snapshots where name='welcome'),4,'filtering invalid/foreign/old/other-context matches precedes the next-four bound');
select is((select value#>>'{sport,items,0,id}'from ot_snapshots where name='welcome'),'own-1','a false is_home_match flag or copied home name cannot authorize another team');
select is((select value#>>'{sport,items,3,id}'from ot_snapshots where name='welcome'),'own-4','the fourth valid authorized kickoff survives invalid earlier candidates');
insert into ot_snapshots values('matchday',private.build_dynamic_snapshot_data(pg_temp.ot_dynamic('matchday','sport_match_of_the_day')));
select is((select value#>>'{sport,matchday,context,tenantId}'from ot_snapshots where name='matchday'),'10000000-0000-4000-8000-000000000285','composite records the canonical tenant');
select is((select jsonb_array_length(value#>'{sport,matchday,standings,items}')from ot_snapshots where name='matchday'),2,'composite keeps the complete authorized standing with nullable source facts');
select is((select value#>>'{sport,matchday,results,items,0,id}'from ot_snapshots where name='matchday'),'played','composite uses actual published results');
select ok((select value#>'{sport,matchday,fixtures,items}'::text[] is not null from ot_snapshots where name='matchday'),'composite includes the program in the same frozen snapshot');
select ok((select not(value#>'{sport,matchday}'::text[])::text like '%wrong-pool%' and not(value#>'{sport,matchday}'::text[])::text like '%wrong-season%'from ot_snapshots where name='matchday'),'composite excludes another pool and season rather than just relabelling them');
